export const app = express();
app.use(express.json());

app.post("/greetings", (req, res) => {
  const name = req.body?.name;

  if (typeof name !== "string" || name.trim() === "") {
    res.status(400).json({ message: "name must be a non-empty string" });
    return;
  }

  res.status(200).json({ greeting: `Hello, ${name.trim()}!` });
});

type HttpResponse = { status: number; body: unknown };

// POST /greetings
export function postGreeting(body: unknown): HttpResponse {
  const name =
    typeof body === "object" && body !== null
      ? (body as Record<string, unknown>).name
      : undefined;

  if (typeof name !== "string" || name.trim().length === 0) {
    return { status: 400, body: { error: "Invalid name." } };
  }

  return { status: 201, body: { greeting: `Hello ${name}` } };
}

